Creating a Terraform module for automated infrastructure cost monitoring involves several steps. Below is a simplified example of how you might structure such a module. This example assumes you have a monitoring API endpoint where the cost analysis report will be sent.

### Directory Structure
```
terraform-module-cost-monitoring/
├── main.tf
├── variables.tf
├── outputs.tf
├── lambda_function/
│   ├── main.tf
│   ├── lambda_function.py
│   ├── requirements.txt
```

### `main.tf`
This file will define the resources needed for the Lambda function and its associated IAM roles and policies.

```hcl
provider "aws" {
  region = var.region
}

resource "aws_iam_role" "lambda_exec_role" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_policy"
  description = "IAM policy for Lambda function"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "iam:Get*",
          "iam:List*",
          "cloudwatch:PutMetricData",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_policy_attachment" {
  role       = aws_iam_role.lambda_exec_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

resource "aws_lambda_function" "cost_monitoring_lambda" {
  filename         = "${path.module}/lambda_function/lambda_function.zip"
  function_name    = "CostMonitoringLambda"
  role             = aws_iam_role.lambda_exec_role.arn
  handler          = "lambda_function.lambda_handler"
  source_code_hash = filebase64sha256("${path.module}/lambda_function/lambda_function.zip")
  runtime          = "python3.8"

  environment {
    variables = {
      MONITORING_API_ENDPOINT = var.monitoring_api_endpoint
    }
  }
}

resource "aws_cloudwatch_event_rule" "every_day" {
  name                = "every-day"
  schedule_expression = "rate(1 day)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.every_day.name
  target_id = "lambda"
  arn       = aws_lambda_function.cost_monitoring_lambda.arn
}

resource "aws_lambda_permission" "allow_cloudwatch" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cost_monitoring_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.every_day.arn
}
```

### `variables.tf`
This file will define the input variables for the module.

```hcl
variable "region" {
  description = "The AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

variable "monitoring_api_endpoint" {
  description = "The endpoint of the monitoring API"
  type        = string
}
```

### `outputs.tf`
This file will define the outputs of the module.

```hcl
output "lambda_function_arn" {
  description = "The ARN of the Lambda function"
  value       = aws_lambda_function.cost_monitoring_lambda.arn
}
```

### `lambda_function/main.tf`
This file will define the resources needed for the Lambda function code.

```hcl
resource "null_resource" "lambda_package" {
  provisioner "local-exec" {
    command = "zip -j ${path.module}/lambda_function.zip ${path.module}/lambda_function.py"
  }

  triggers = {
    always_run = "${timestamp()}"
  }
}
```

### `lambda_function/lambda_function.py`
This file will contain the Python code for the Lambda function.

```python
import boto3
import json
import os
import requests

def lambda_handler(event, context):
    monitoring_api_endpoint = os.getenv('MONITORING_API_ENDPOINT')

    # Initialize AWS clients
    ec2 = boto3.client('ec2')
    iam = boto3.client('iam')

    # Collect IAM policies
    iam_policies = iam.list_policies()['Policies']

    # Collect access keys
    access_keys = []
    for user in iam.list_users()['Users']:
        access_keys.extend(iam.list_access_keys(UserName=user['UserName'])['AccessKeyMetadata'])

    # Collect security group rules
    security_groups = ec2.describe_security_groups()['SecurityGroups']

    # Collect all resources (simplified example)
    resources = {
        'iam_policies': iam_policies,
        'access_keys': access_keys,
        'security_groups': security_groups
    }

    # Send the report to the monitoring API
    response = requests.post(monitoring_api_endpoint, json=resources)
    if response.status_code == 200:
        print("Report sent successfully")
    else:
        print(f"Failed to send report: {response.status_code}")

    return {
        'statusCode': 200,
        'body': json.dumps('Cost monitoring report sent')
    }
```

### `lambda_function/requirements.txt`
This file will list the Python dependencies for the Lambda function.

```
boto3
requests
```

### Usage
To use this module, you would include it in your Terraform configuration like this:

```hcl
module "cost_monitoring" {
  source = "./terraform-module-cost-monitoring"

  region                  = "us-west-2"
  monitoring_api_endpoint = "https://your-monitoring-api-endpoint.com/report"
}
```

This example provides a basic structure and functionality. You may need to adjust it based on your specific requirements and the complexity of your infrastructure.

Creating a Terraform configuration to set up an automated compliance checker involves several steps. This includes creating an AWS Lambda function, setting up an IAM role for the Lambda function, creating a CloudWatch Event rule to trigger the Lambda function periodically, and configuring the Lambda function to read the Terraform state file and post a compliance report to an external audit platform.

Below is a Terraform configuration that accomplishes this:

1. **IAM Role for Lambda**: This role will allow the Lambda function to read the Terraform state file from an S3 bucket and to post data to an external audit platform.
2. **Lambda Function**: This function will read the Terraform state file, extract resource configurations, and post a compliance report.
3. **CloudWatch Event Rule**: This rule will trigger the Lambda function periodically.

### Terraform Configuration

```hcl
provider "aws" {
  region = "us-west-2"
}

# S3 Bucket for Terraform State File
resource "aws_s3_bucket" "terraform_state" {
  bucket = "your-terraform-state-bucket"
  acl    = "private"
}

# IAM Role for Lambda
resource "aws_iam_role" "lambda_role" {
  name = "lambda_compliance_checker_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_compliance_checker_policy"
  description = "Policy for Lambda compliance checker"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ],
        Effect   = "Allow",
        Resource = [
          aws_s3_bucket.terraform_state.arn,
          "${aws_s3_bucket.terraform_state.arn}/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ],
        Effect   = "Allow",
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_policy_attachment" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

# Lambda Function
resource "aws_lambda_function" "compliance_checker" {
  filename         = "lambda_function_payload.zip"
  function_name    = "compliance_checker"
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.handler"
  runtime          = "python3.8"
  source_code_hash = filebase64sha256("lambda_function_payload.zip")

  environment {
    variables = {
      TERRAFORM_STATE_BUCKET = aws_s3_bucket.terraform_state.bucket
      AUDIT_PLATFORM_URL    = "https://your-audit-platform.com/api/report"
    }
  }
}

# CloudWatch Event Rule
resource "aws_cloudwatch_event_rule" "every_day" {
  name                = "every-day"
  description         = "Fires every day at 12 PM UTC"
  schedule_expression = "cron(0 12 * * ? *)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.every_day.name
  target_id = "compliance_checker"
  arn       = aws_lambda_function.compliance_checker.arn
}

resource "aws_lambda_permission" "allow_cloudwatch" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.compliance_checker.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.every_day.arn
}
```

### Lambda Function Code

You need to create a Lambda function code that reads the Terraform state file from the S3 bucket, extracts resource configurations, and posts a compliance report to the external audit platform. Below is a sample Python code for the Lambda function:

```python
import json
import boto3
import requests
import base64

s3 = boto3.client('s3')

def handler(event, context):
    bucket_name = os.environ['TERRAFORM_STATE_BUCKET']
    audit_platform_url = os.environ['AUDIT_PLATFORM_URL']

    # Read the Terraform state file from S3
    response = s3.get_object(Bucket=bucket_name, Key='terraform.tfstate')
    state_file_content = response['Body'].read().decode('utf-8')
    state = json.loads(state_file_content)

    # Extract resource configurations
    resources = state['resources']
    compliance_report = []

    for resource in resources:
        resource_type = resource['type']
        resource_name = resource['name']
        resource_config = resource['instances'][0]['attributes']

        # Example: Check for sensitive data (this is a simplified example)
        if 'password' in resource_config or 'secret' in resource_config:
            compliance_report.append({
                'resource_type': resource_type,
                'resource_name': resource_name,
                'issue': 'Sensitive data found'
            })

    # Post compliance report to external audit platform
    headers = {'Content-Type': 'application/json'}
    response = requests.post(audit_platform_url, headers=headers, data=json.dumps(compliance_report))

    if response.status_code == 200:
        print("Compliance report posted successfully")
    else:
        print(f"Failed to post compliance report: {response.status_code}")

    return {
        'statusCode': 200,
        'body': json.dumps('Compliance check completed')
    }
```

### Packaging the Lambda Function

1. Create a directory for your Lambda function code.
2. Save the Python code above in a file named `index.py`.
3. Create a `requirements.txt` file with the necessary dependencies (e.g., `boto3` and `requests`).
4. Zip the contents of the directory.

```sh
zip -r lambda_function_payload.zip index.py requirements.txt
```

### Deploying the Lambda Function

1. Upload the `lambda_function_payload.zip` to your Terraform configuration directory.
2. Apply the Terraform configuration.

```sh
terraform init
terraform apply
```

This setup will create an AWS Lambda function that runs periodically, reads the Terraform state file from an S3 bucket, extracts resource configurations, and posts a compliance report to an external audit platform.

